 * Initialize A and B as in the original C version:
 *
 *   A[i][j][k] = B[i][j][k] = (i + j + (n - k)) * 10 / n;
 *
 * Mapping from C arrays to Halide buffers:
 *   C: DATA_TYPE A[N][N][N] accessed as A[i][j][k]
 *   Halide: Buffer<num_t, 3> A(k, j, i)  // dim 0 = k, dim 1 = j, dim 2 = i
 *
 * So A[i][j][k] in C becomes A(k, j, i) in Halide.
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 3> A,
                       Halide::Buffer<num_t, 3> B) {
    // k, j, i correspond to C's k, j, i, but in Halide they are (dim0, dim1, dim2)
    Var k("k"), j("j"), i("i");

    Func init("init");

    // Use Expr literals to avoid implicit type surprises.
    Expr ten = cast<num_t>(Expr(10));
    Expr nn  = cast<num_t>(Expr(n));

    // i, j, k here are the C-style indices; buffer indices are (k, j, i)
    Expr val = cast<num_t>(i + j + (n - k)) * ten / nn;
    init(k, j, i) = val;

    // ----------------------------------------------------------------------------
    // Schedule for initialization:
    // - k is the innermost dimension and is contiguous in memory.
    // - Tile over (i, j) for cache locality.
    // - Parallelize across tiles.
    // - Vectorize along k.
    // ----------------------------------------------------------------------------
    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) {
        vec_width = 1;
    }

    // Tunable tile sizes for spatial dimensions (C's i, j).
    const int tile_i = 4;
    const int tile_j = 4;

    Var io("io"), jo("jo"), ii("ii"), ji("ji"), tile("tile");

    init
        // Tile the outer (i, j) loops.
        .tile(i, j, io, jo, ii, ji, tile_i, tile_j)
        // Fuse tiles into a single parallel dimension.
        .fuse(io, jo, tile)
        .parallel(tile)
        // Make k the innermost loop (contiguous) for vectorization.
        // Order is specified from innermost to outermost.
        .reorder(k, ii, ji, tile)
        .vectorize(k, vec_width)
        // Small inner tiles: unroll for a bit more ILP.
        .unroll(ii)
        .unroll(ji);

    // Realize into both A and B so that B initially equals A.
    // We execute the scheduled pipeline twice rather than building
    // a separate copy stage; this is a one-time cost.
    init.realize(A);
    init.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size and number of time steps.
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate 3D buffers.
    // Dimension order is (k, j, i) so that:
    //   A(i,j,k in C) <-> A(k, j, i) in Halide.
    Halide::Buffer<num_t, 3> A(n, n, n);
    Halide::Buffer<num_t, 3> B(n, n, n);

    // Initialize A and B.
    init_array(n, A, B);

    // Create ImageParams for A and B so that Halide pipelines can read them.
    ImageParam A_param(type_of<num_t>(), 3, "A_param");
    ImageParam B_param(type_of<num_t>(), 3, "B_param");

    A_param.set(A);
    B_param.set(B);

    // Vars for 3D indexing (k, j, i) <-> (C's k, j, i).
    Var k("k"), j("j"), i("i");

    // One time-step consists of:
    //   1) B = stencil(A)
    //   2) A = stencil(B)
    //
    // We'll express these as two separate Halide Funcs:
    //   B_from_A: reads A_param, writes into B
    //   A_from_B: reads B_param, writes into A
    //
    // We only update interior points (i,j,k in [1, n-2]), as in the
    // original C loops. The boundaries remain unchanged.
    Func B_from_A("B_from_A");
    Func A_from_B("A_from_B");

    // Numeric constants as Exprs, then cast to num_t.
    Expr alpha = cast<num_t>(Expr(0.125)); // 1/8
    Expr two   = cast<num_t>(Expr(2.0));

    // --- Stage 1: B = stencil(A) ---
    {
        Expr centerA = A_param(k, j, i);

        Expr term_i = alpha *
                      (A_param(k, j, i + 1) - two * centerA + A_param(k, j, i - 1));
        Expr term_j = alpha *
                      (A_param(k, j + 1, i) - two * centerA + A_param(k, j - 1, i));
        Expr term_k = alpha *
                      (A_param(k + 1, j, i) - two * centerA + A_param(k - 1, j, i));

        B_from_A(k, j, i) = term_i + term_j + term_k + centerA;
    }

    // --- Stage 2: A = stencil(B) ---
    {
        Expr centerB = B_param(k, j, i);

        Expr term_i = alpha *
                      (B_param(k, j, i + 1) - two * centerB + B_param(k, j, i - 1));
        Expr term_j = alpha *
                      (B_param(k, j + 1, i) - two * centerB + B_param(k, j - 1, i));
        Expr term_k = alpha *
                      (B_param(k + 1, j, i) - two * centerB + B_param(k - 1, j, i));

        A_from_B(k, j, i) = term_i + term_j + term_k + centerB;
    }

    // ----------------------------------------------------------------------------
    // Scheduling of the two stencil kernels
    //
    // Memory layout:
    //   - Halide Buffer uses dimension 0 as the fastest-varying, so k is
    //     contiguous in memory.
    //   - We therefore vectorize along k and tile in (i, j) for cache locality.
    //   - We parallelize across (i, j) tiles, fusing them into a 1D index
    //     so as to avoid nested parallelism.
    // ----------------------------------------------------------------------------
    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) {
        vec_width = 1;
