    const int tile_i = 4;  // along C's i (Halide dim 2)
    const int tile_j = 4;  // along C's j (Halide dim 1)

    Var io("io"), jo("jo"), ii("ii"), ji("ji"), tile("tile");

    // Schedule for B_from_A: B = stencil(A)
    B_from_A
        .compute_root()
        // Tile over (i, j).
        .tile(i, j, io, jo, ii, ji, tile_i, tile_j)
        // Fuse the tile coordinates to get a single parallel loop.
        .fuse(io, jo, tile)
        .parallel(tile)
        // Make k innermost for contiguous, vectorized access.
        // Order is from innermost to outermost.
        .reorder(k, ii, ji, tile)
        .vectorize(k, vec_width)
        .unroll(ii)
        .unroll(ji);

    // Schedule for A_from_B: A = stencil(B)
    // Same pattern as above for balanced performance.
    A_from_B
        .compute_root()
        .tile(i, j, io, jo, ii, ji, tile_i, tile_j)
        .fuse(io, jo, tile)
        .parallel(tile)
        .reorder(k, ii, ji, tile)
        .vectorize(k, vec_width)
        .unroll(ii)
        .unroll(ji);

    // We want to update only the interior region:
    //   i, j, k in [1, n-2]
    // The boundary values remain unchanged (exactly as in the C code).
    //
    // We'll realize into cropped "interior" views that alias the
    // underlying A and B storage, so that:
    //   - interior points are overwritten by the stencil
    //   - boundary points (index 0 and n-1) are untouched
